{
  "implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    segments = case.get("segments")
    if not isinstance(segments, list):
        raise ValueError("segments must be a list")
    budget = case.get("budget")
    if not isinstance(budget, int):
        raise ValueError("budget must be an int")
    for s in segments:
        if not isinstance(s, dict):
            raise ValueError("each segment must be a dict")
        for key in ('name','importance','minimum','capacity'):
            if key not in s:
                raise ValueError(f"missing {key} in segment")
            if not isinstance(s[key], int):
                raise ValueError(f"{key} must be int")
    sum_minima = sum(s['minimum'] for s in segments)
    sum_capacity = sum(s['capacity'] for s in segments)
    if budget < sum_minima:
        raise ValueError("budget less than sum of minima")
    if budget > sum_capacity:
        raise ValueError("budget exceeds total capacity")
    alloc = [s['minimum'] for s in segments]
    remaining = budget - sum_minima
    n = len(segments)
    while remaining > 0:
        best_idx = None
        best_ratio = -1.0
        for i in range(n):
            if alloc[i] < segments[i]['capacity']:
                ratio = segments[i]['importance'] / (alloc[i] + 1)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
        if best_idx is None:
            raise ValueError("unable to allocate remaining budget")
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    total = sum(alloc)
    return {
        "allocations": alloc,
        "by_name": by_name,
        "total": total
    }"
}
